func TestDefaultTensor(t *testing.T) {
	o := &Tensor{}
	if o == nil {
		t.Fatal("expected non-nil")
	}
}


func TestUnionTensorType(t *testing.T) {
	for _, v := range []schema.Type{
		&schema.Null{},
		&schema.Int{},
		&schema.FloatingPoint{},
		&schema.Binary{},
		&schema.Utf8{},
		&schema.Bool{},
		&schema.Decimal{},
		&schema.Date{},
		&schema.Time{},
		&schema.Timestamp{},
		&schema.Interval{},
		&schema.List{},
		&schema.Struct{},
		&schema.Union{},
		&schema.FixedSizeBinary{},
		&schema.FixedSizeList{},
		&schema.Map{},
		&schema.Duration{},
		&schema.LargeBinary{},
		&schema.LargeUtf8{},
		&schema.LargeList{},
		&schema.RunEndEncoded{},
		&schema.BinaryView{},
		&schema.Utf8view{},
		&schema.ListView{},
		&schema.LargeListView{},
	} {
		o := &Tensor{Type: v}
		got, err := TensorFromBytes(o.ToBytes())
		if err != nil {
			t.Fatalf("%T: deserialization failed: %v", v, err)
		}
		if fmt.Sprintf("%T", got.Type) != fmt.Sprintf("%T", v) {
			t.Fatalf("got %T, want %T", got.Type, v)
		}
	}
}

func TestVectorPresenceTensor(t *testing.T) {
	o := &Tensor{}
	var fbs *generated.Tensor
	fbs = generated.GetSizePrefixedRootAsTensor(o.ToBytes(), 0)
	if tbl := fbs.Table(); tbl.Offset(10) != 0 {
		t.Errorf("Strides: nil vector is written")
	}
	o.Strides = emptyOf(o.Strides)
	data := o.ToBytes()
	fbs = generated.GetSizePrefixedRootAsTensor(data, 0)
	if tbl := fbs.Table(); tbl.Offset(10) == 0 {
		t.Errorf("Strides: empty vector is not written")
	}
	got, err := TensorFromBytes(data)
	if err != nil {
		t.Fatalf("deserialization failed: %v", err)
	}
	if got.Strides == nil {
		t.Errorf("Strides: empty vector is read back as nil")
	}
}

